// === Tab: mySketch ===
let myShader;
let gr;
let properFrameCount = 0;

let vs =
"precision mediump float;" +
"attribute vec3 aPosition;" +
"void main(){" +
"  gl_Position = vec4(aPosition, 1.0);" +
"}";

let fs =
"precision mediump float;" +
"uniform vec2 uResolution;" +
"uniform float uCount;" +
"const float TAU = 6.28318;" +
"const vec2 e0 = vec2(1.0, 0.0);" +
"const vec2 e1 = vec2(0.0, 1.0);" +
// hsb to rgb.
"vec3 getRGB(float h, float s, float b){" +
"    vec3 c = vec3(h, s, b);" +
"    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);" +
"    rgb = rgb * rgb * (3.0 - 2.0 * rgb);" +
"    return c.z * mix(vec3(1.0), rgb, c.y);" +
"}" +
"vec2 zhu(vec2 p){" +
"  float m = p.x * p.x + p.y * p.y;" +
"  return vec2(p.x + 0.25 * p.x / m, p.y - 0.25 * p.y / m);" +
"}" +
"void main(){" +
"  vec2 p = (gl_FragCoord.xy - uResolution.xy) / min(uResolution.x, uResolution.y);" +
"  vec2 q = zhu(p);" +
//"  q = p;" +
"  float s = uCount / 480.0;" +
"  q *= mat2(cos(s), sin(s), -sin(s), cos(s));" +
"  q = 2.0 * (fract(q * 10.0) - 0.5);" +
"  vec3 col = getRGB(.75, abs(q.x*q.x-q.y*q.y)*4.0, pow(length(p), 0.75));" +
"  gl_FragColor = vec4(col, 1.0);" +
"}";

function setup() {
  createCanvas(1112, 834);
  gr = createGraphics(width, height, WEBGL);
  myShader = gr.createShader(vs, fs);
  gr.shader(myShader);
}

function draw() {
  clear();
  myShader.setUniform("uResolution", [width, height]);
  myShader.setUniform("uCount", properFrameCount);
  gr.quad(-1, -1, -1, 1, 1, 1, 1, -1);
  image(gr, 0, 0);
  properFrameCount++;
}

